func (this *Cursor_ImageDataWithMaskCursorHandleProvider) ValidateMask(sourceLike ImageDataLike, maskLike ImageDataLike) {
	var source *ImageData
	if sourceLike != nil {
		source = sourceLike.AsImageData()
	}
	_ = source
	var mask *ImageData
	if maskLike != nil {
		mask = maskLike.AsImageData()
	}
	_ = mask
	var effectiveMask *ImageData = mask
	if effectiveMask == (nil) {
		if source.GetTransparencyType() != TRANSPARENCY_MASK {
			Error(ERROR_NULL_ARGUMENT)
		}
		effectiveMask = source.GetTransparencyMask()
	}
	if effectiveMask.Width != source.Width || effectiveMask.Height != source.Height {
		Error(ERROR_INVALID_ARGUMENT)
	}
}

func (this *Cursor_ImageDataWithMaskCursorHandleProvider) createHandle_(device *Device, zoom int32) *Cursor_CursorHandle {
	var scaledZoomFactor float32 = float32(zoom) / 100
	var scaledSourceWidth int32 = int32(math.Floor(float64(float32(this.source.Width)*scaledZoomFactor) + 0.5))
	var scaledSourceHeight int32 = int32(math.Floor(float64(float32(this.source.Height)*scaledZoomFactor) + 0.5))
	var scaledSource *ImageData = this.source.ScaledTo(scaledSourceWidth, scaledSourceHeight)
	var scaledMask *ImageData = nil
	if this.mask != (nil) {
		var scaledMaskWidth int32 = int32(math.Floor(float64(float32(this.mask.Width)*scaledZoomFactor) + 0.5))
		var scaledMaskHeight int32 = int32(math.Floor(float64(float32(this.mask.Height)*scaledZoomFactor) + 0.5))
		scaledMask = this.mask.ScaledTo(scaledMaskWidth, scaledMaskHeight)
	}
	return CursorSetupCursorFromImageData(device, scaledSource, scaledMask, this.GetHotpotXInPixels(zoom), this.GetHotpotYInPixels(zoom))
}

